PROCEDURE @@proc@@ (p_run_id IN NUMBER) IS
BEGIN
    FOR rec IN (SELECT id, @@col@@ FROM @@tab@@ WHERE run_id = p_run_id) LOOP
        INSERT INTO @@tab2@@ (id, @@col@@, loaded_at) -- @expect
        VALUES (rec.id, rec.@@col@@, SYSDATE);
    END LOOP;
    DBMS_OUTPUT.PUT_LINE('loaded run ' || p_run_id);
END @@proc@@;

PROCEDURE @@proc@@ (p_dept IN NUMBER, p_pct IN NUMBER) IS
    CURSOR c_rows (p_d NUMBER) IS
        SELECT id, @@col@@
          FROM @@tab@@
         WHERE dept_id = p_d;
BEGIN
    FOR rec IN c_rows(p_dept) LOOP
        UPDATE @@tab@@ -- @expect
           SET @@col@@ = rec.@@col@@ * p_pct
         WHERE id = rec.id;
    END LOOP;
END @@proc@@;

PROCEDURE @@proc@@ IS
    CURSOR c_old IS
        SELECT id FROM @@tab@@ WHERE @@col@@ IS NULL;
    l_row c_old%ROWTYPE;
BEGIN
    OPEN c_old;
    LOOP
        FETCH c_old INTO l_row;
        EXIT WHEN c_old%NOTFOUND;
        DELETE FROM @@tab2@@ WHERE ref_id = l_row.id; -- @expect
    END LOOP;
    CLOSE c_old;
END @@proc@@;

PROCEDURE @@proc@@ IS
    CURSOR c_src IS
        SELECT id, qty FROM @@tab@@;
BEGIN
    FOR rec IN c_src LOOP
        FOR n IN 1 .. rec.qty LOOP
            INSERT INTO @@tab2@@ (src_id, seq) -- @expect
            VALUES (rec.id, n);
        END LOOP;
    END LOOP;
END @@proc@@;

PROCEDURE @@proc@@ (p_factor IN NUMBER) IS
    CURSOR c_lock IS
        SELECT @@col@@ FROM @@tab@@ WHERE @@col2@@ IS NOT NULL FOR UPDATE;
BEGIN
    FOR rec IN c_lock LOOP
        UPDATE @@tab@@ SET @@col@@ = rec.@@col@@ * p_factor WHERE CURRENT OF c_lock; -- @expect
    END LOOP;
END @@proc@@;

