PROCEDURE @@proc@@ (p_ids IN SYS.ODCINUMBERLIST) IS
    l_errors PLS_INTEGER;
BEGIN
    FORALL i IN 1 .. p_ids.COUNT SAVE EXCEPTIONS
        DELETE FROM @@tab@@
         WHERE id = p_ids(i);
EXCEPTION
    WHEN OTHERS THEN
        IF SQLCODE = -24381 THEN
            l_errors := SQL%BULK_EXCEPTIONS.COUNT;
            FOR j IN 1 .. l_errors LOOP
                DBMS_OUTPUT.PUT_LINE(SQL%BULK_EXCEPTIONS(j).ERROR_CODE);
            END LOOP;
        ELSE
            RAISE;
        END IF;
END @@proc@@;

PROCEDURE @@proc@@ (p_n IN PLS_INTEGER) IS
BEGIN
    FOR i IN 1 .. p_n LOOP
        INSERT INTO @@tab@@ (seq, created_at)
        VALUES (i, SYSDATE);
    END LOOP;
    DBMS_OUTPUT.PUT_LINE('inserted ' || p_n);
END @@proc@@;

PROCEDURE @@proc@@ (p_run_id IN NUMBER) IS
    TYPE t_ids IS TABLE OF NUMBER INDEX BY PLS_INTEGER;
    l_ids t_ids;
BEGIN
    SELECT id
      BULK COLLECT INTO l_ids
      FROM @@tab@@
     WHERE run_id = p_run_id;

    FORALL i IN 1 .. l_ids.COUNT
        UPDATE @@tab2@@
           SET @@col@@ = SYSDATE
         WHERE id = l_ids(i);
END @@proc@@;

PROCEDURE @@proc@@ (p_dept IN NUMBER) IS
    CURSOR c_emp (p_d NUMBER) IS
        SELECT id, @@col@@ FROM @@tab@@ WHERE dept_id = p_d;
BEGIN
    FOR rec IN c_emp(p_dept) LOOP
        @@proc2@@(rec.id, rec.@@col@@);
    END LOOP;
    FOR rec IN (SELECT id FROM @@tab2@@) LOOP
        DBMS_OUTPUT.PUT_LINE(rec.id);
    END LOOP;
END @@proc@@;

PROCEDURE @@proc@@ (p_id IN NUMBER) IS
    l_attempts PLS_INTEGER := 0;
BEGIN
    LOOP
        l_attempts := l_attempts + 1;
        UPDATE @@tab@@
           SET @@col@@ = l_attempts
         WHERE id = p_id;
        EXIT;
    END LOOP;
END @@proc@@;
